changeSet.sql:
ALTER TABLE sciences ALTER COLUMN id SET DEFAULT nextval('sciences_seq');
ALTER TABLE authorities ALTER COLUMN id SET DEFAULT nextval('authorities');
ALTER TABLE balance_transactions ALTER COLUMN id SET DEFAULT nextval('balance_transactions');
ALTER TABLE balances ALTER COLUMN id SET DEFAULT nextval('balances_seq');
ALTER TABLE comments ALTER COLUMN id SET DEFAULT nextval('comments');
ALTER TABLE course_grades ALTER COLUMN id SET DEFAULT nextval('course_grades');
ALTER TABLE course_lessons ALTER COLUMN id SET DEFAULT nextval('course_lessons');
ALTER TABLE courses ALTER COLUMN id SET DEFAULT nextval('courses');
ALTER TABLE files ALTER COLUMN id SET DEFAULT nextval('files_seq');
ALTER TABLE lesson_progresses ALTER COLUMN id SET DEFAULT nextval('lesson_progresses_seq');
ALTER TABLE payments ALTER COLUMN id SET DEFAULT nextval('payments_seq');
ALTER TABLE refresh_tokens ALTER COLUMN id SET DEFAULT nextval('refresh_tokens_seq');
ALTER TABLE test_options ALTER COLUMN id SET DEFAULT nextval('test_options_seq');
ALTER TABLE test_questions ALTER COLUMN id SET DEFAULT nextval('test_questions_seq');
ALTER TABLE test_session_answers ALTER COLUMN id SET DEFAULT nextval('test_session_answers');
ALTER TABLE test_session_options ALTER COLUMN id SET DEFAULT nextval('test_session_options_seq');
ALTER TABLE test_session_questions ALTER COLUMN id SET DEFAULT nextval('test_session_questions_seq');
ALTER TABLE test_sessions ALTER COLUMN id SET DEFAULT nextval('test_sessions_seq');
ALTER TABLE tests ALTER COLUMN id SET DEFAULT nextval('tests_seq');
ALTER TABLE top_up_requests ALTER COLUMN id SET DEFAULT nextval('top_up_req_seq');
ALTER TABLE users ALTER COLUMN id SET DEFAULT nextval('users_seq');
